/**
 * Constants shared by the Saved (collections based) experience.
 *
 * The values below are the production identifiers used by the Saved surface:
 * they are referenced from persistence keys, database rows and the observable
 * UI state, therefore they must stay stable across releases.
 */

/** Language used when an article is presented without an explicit wiki language. */
export const DEFAULT_LANGUAGE_CODE: string = 'en';

/**
 * Title of the implicit collection that holds every saved article that has not
 * been moved into a user created collection. It is never listed on the
 * Collections tab and it can never be deleted.
 */
export const DEFAULT_COLLECTION_TITLE: string = 'Saved';

/* -------------------------------------------------------------------------- */
/* Tabs                                                                       */
/* -------------------------------------------------------------------------- */

export const TAB_ALL_ARTICLES: string = 'ALL_ARTICLES';
export const TAB_COLLECTIONS: string = 'COLLECTIONS';
export type SavedTab = 'ALL_ARTICLES' | 'COLLECTIONS';

export function isSavedTab(value: string): boolean {
  return value === TAB_ALL_ARTICLES || value === TAB_COLLECTIONS;
}

/* -------------------------------------------------------------------------- */
/* Article filter (All articles tab only)                                     */
/* -------------------------------------------------------------------------- */

export const ARTICLE_FILTER_ALL_ARTICLES: string = 'ALL_ARTICLES';
/** Shows only articles that are held exclusively by the default collection. */
export const ARTICLE_FILTER_NOT_IN_COLLECTION: string = 'NOT_IN_COLLECTION';
export type SavedArticleFilter = 'ALL_ARTICLES' | 'NOT_IN_COLLECTION';

export function isArticleFilter(value: string): boolean {
  return value === ARTICLE_FILTER_ALL_ARTICLES || value === ARTICLE_FILTER_NOT_IN_COLLECTION;
}

/* -------------------------------------------------------------------------- */
/* Sort modes                                                                 */
/* -------------------------------------------------------------------------- */

/** Sorting is persisted independently for the article and the collection view. */
export const SORT_BY_NAME_ASC: number = 0;
export const SORT_BY_NAME_DESC: number = 1;
export const SORT_BY_DATE_ADDED: number = 2;
export const SORT_BY_DATE_LAST_UPDATED: number = 3;
export type SavedSortMode = number;

export const ARTICLE_SORT_CHOICES: number[] =
  [SORT_BY_NAME_ASC, SORT_BY_NAME_DESC, SORT_BY_DATE_ADDED, SORT_BY_DATE_LAST_UPDATED];
export const COLLECTION_SORT_CHOICES: number[] = [SORT_BY_NAME_ASC, SORT_BY_NAME_DESC];

export function isSortMode(mode: number, choices: number[]): boolean {
  return choices.indexOf(mode) >= 0;
}

export function sortModeLabel(mode: number): string {
  if (mode === SORT_BY_NAME_DESC) {
    return 'Sort by name descending';
  }
  if (mode === SORT_BY_DATE_ADDED) {
    return 'Sort by date added';
  }
  if (mode === SORT_BY_DATE_LAST_UPDATED) {
    return 'Sort by date last updated';
  }
  return 'Sort by name ascending';
}

/* -------------------------------------------------------------------------- */
/* Reading list page (membership) statuses                                     */
/* -------------------------------------------------------------------------- */

export const STATUS_ACTIVE: string = 'ACTIVE';
/**
 * Membership rows that are queued for deletion are still persisted so that the
 * action can be undone, but they are filtered out of every active projection.
 */
export const STATUS_QUEUE_FOR_DELETE: string = 'STATUS_QUEUE_FOR_DELETE';
export const STATUS_DELETED: string = 'STATUS_DELETED';
export type ReadingListPageStatus = string;

export function isProjectedStatus(status: string): boolean {
  return status === STATUS_ACTIVE;
}

/* -------------------------------------------------------------------------- */
/* Empty states                                                               */
/* -------------------------------------------------------------------------- */

export const EMPTY_STATE_NONE: string = 'NONE';
export const EMPTY_STATE_LOADING: string = 'LOADING';
export const EMPTY_STATE_SEARCH_NO_RESULTS: string = 'SEARCH_NO_RESULTS';
export const EMPTY_STATE_NO_ARTICLES: string = 'NO_ARTICLES';
export const EMPTY_STATE_NO_COLLECTIONS: string = 'NO_COLLECTIONS';
export const EMPTY_STATE_NO_COLLECTION_CONTENT: string = 'NO_COLLECTION_CONTENT';
export const EMPTY_STATE_NOTHING_SELECTED: string = 'NOTHING_SELECTED';
export type SavedEmptyState = string;

/* -------------------------------------------------------------------------- */
/* Onboarding                                                                 */
/* -------------------------------------------------------------------------- */

export const ONBOARDING_NONE: string = 'NONE';
export const ONBOARDING_SYNC_REMINDER: string = 'SYNC_REMINDER';
export const ONBOARDING_LOGIN_REMINDER: string = 'LOGIN_REMINDER';
export const ONBOARDING_SHARED_COLLECTION: string = 'SHARED_COLLECTION';
export type SavedOnboardingState = string;

/* -------------------------------------------------------------------------- */
/* Feedback                                                                   */
/* -------------------------------------------------------------------------- */

export const FEEDBACK_SEVERITY_INFO: string = 'INFO';
export const FEEDBACK_SEVERITY_WARNING: string = 'WARNING';
export const FEEDBACK_SEVERITY_ERROR: string = 'ERROR';
export const FEEDBACK_ACTION_UNDO: string = 'UNDO';
export const FEEDBACK_ACTION_DISMISS: string = 'DISMISS';

/* -------------------------------------------------------------------------- */
/* Limits                                                                     */
/* -------------------------------------------------------------------------- */

/** Maximum number of articles a single collection may hold. */
export const MAX_ARTICLES_PER_COLLECTION: number = 1000;
/** Maximum number of user created collections one account may own. */
export const MAX_COLLECTIONS_PER_USER: number = 100;

export const LIMIT_REASON_COLLECTION_FULL: string = 'COLLECTION_ARTICLE_LIMIT_REACHED';
export const LIMIT_REASON_COLLECTION_COUNT: string = 'COLLECTION_COUNT_LIMIT_REACHED';

export const LIMIT_MESSAGE_COLLECTION_FULL: string =
  'This collection already holds the maximum number of articles.';
export const LIMIT_MESSAGE_COLLECTION_COUNT: string =
  'You already own the maximum number of collections.';

/* -------------------------------------------------------------------------- */
/* Behavioural constants                                                      */
/* -------------------------------------------------------------------------- */

/** Search input is debounced; the delay is part of the production behaviour. */
export const SEARCH_DEBOUNCE_MILLIS: number = 150;
/** Undo snackbar lifetime. */
export const FEEDBACK_VISIBLE_MILLIS: number = 5000;
/** Sort preferences are kept separately for the two views. */
export const PREFERENCE_ARTICLE_SORT_MODE: string = 'saved_article_sort_mode';
export const PREFERENCE_COLLECTION_SORT_MODE: string = 'saved_collection_sort_mode';
export const PREFERENCE_LAST_TAB: string = 'saved_last_tab';
export const PREFERENCE_SYNC_ENABLED: string = 'reading_list_sync_enabled';
export const PREFERENCE_DATABASE_SNAPSHOT: string = 'saved_database_snapshot';
export const PREFERENCE_SNAPSHOT_KEY: string = 'snapshot';
export const PREFERENCE_STORE_NAME: string = 'saved_surface';

/**
 * Logical identity of a Wikipedia article as used by the Saved experience.
 *
 * The identity of a saved article is the pair of wiki language code and API
 * (storage) title. Display titles are presentation only: two saved rows that
 * point at the same language/title pair are the same logical article even when
 * they are stored in several collections.
 */
import { DEFAULT_LANGUAGE_CODE } from './SavedConstants';

export class PageTitle {
  readonly languageCode: string;
  readonly apiTitle: string;
  readonly displayTitle: string;

  constructor(languageCode: string, apiTitle: string, displayTitle: string) {
    this.languageCode = languageCode && languageCode.length > 0 ? languageCode : DEFAULT_LANGUAGE_CODE;
    this.apiTitle = apiTitle;
    this.displayTitle = displayTitle && displayTitle.length > 0
      ? displayTitle
      : PageTitle.deriveDisplayTitle(this.apiTitle);
  }

  /** Canonical string form: `<language>:<apiTitle>`. */
  get identity(): string {
    return this.languageCode + ':' + this.apiTitle;
  }

  get language(): string {
    return this.languageCode;
  }

  get title(): string {
    return this.apiTitle;
  }

  equals(other: PageTitle): boolean {
    return other !== undefined && other !== null && other.identity === this.identity;
  }

  /** True when both titles denote the same logical article. */
  static sameIdentity(left: PageTitle, right: PageTitle): boolean {
    return left !== undefined && left !== null && left.identity === right.identity;
  }

  toString(): string {
    return this.identity;
  }

  static fromIdentity(identity: string): PageTitle {
    const separator = identity.indexOf(':');
    if (separator <= 0 || separator === identity.length - 1) {
      return new PageTitle(DEFAULT_LANGUAGE_CODE, identity, PageTitle.deriveDisplayTitle(identity));
    }
    const language = identity.substring(0, separator);
    const apiTitle = identity.substring(separator + 1);
    return new PageTitle(language, apiTitle, PageTitle.deriveDisplayTitle(apiTitle));
  }

  static deriveDisplayTitle(apiTitle: string): string {
    return PageTitle.decodeUriComponent(apiTitle.replace(/_/g, ' '));
  }

  private static decodeUriComponent(value: string): string {
    if (value.indexOf('%') < 0) {
      return value;
    }
    try {
      return decodeURIComponent(value);
    } catch (error) {
      // A malformed escape sequence is not a reason to fail a save operation;
      // the raw text is still a usable display title.
      return value;
    }
  }
}

/**
 * Minimal reactive stream used by the reading list data layer.
 *
 * The database exposes a change flow; derived queries subscribe to it and push
 * freshly projected values to their own collectors. This is what lets the Saved
 * page update when the underlying membership tables change without anybody
 * rebuilding the page by hand.
 */
export type FlowCallback<T> = (value: T) => void;

export class Flow<T> {
  private current: T;
  private readonly callbacks: FlowCallback<T>[] = [];

  constructor(initial: T) {
    this.current = initial;
  }

  getValue(): T {
    return this.current;
  }

  /**
   * Registers a collector and immediately replays the latest value so that a
   * late subscriber never misses the current snapshot.
   */
  collect(callback: FlowCallback<T>): void {
    this.callbacks.push(callback);
    callback(this.current);
  }

  /** Number of live collectors. */
  collectorCount(): number {
    return this.callbacks.length;
  }

  emit(value: T): void {
    this.current = value;
    for (let index = 0; index < this.callbacks.length; index++) {
      this.callbacks[index](value);
    }
  }
}

/**
 * Room style entities for the Saved feature.
 *
 * `RoomListEntity` is a collection. `ReadingListPageEntity` is a single
 * membership row: it links one article (PageTitle) to one collection. An
 * article that belongs to three collections therefore has three membership
 * rows, but exactly one logical article.
 */
import { PageTitle } from './PageTitle';
import { DEFAULT_COLLECTION_TITLE, STATUS_ACTIVE, STATUS_QUEUE_FOR_DELETE } from './SavedConstants';

export class RoomListEntity {
  readonly id: number;
  title: string;
  description: string;
  readonly isDefault: boolean;
  rank: number;
  readonly createdAt: number;
  updatedAt: number;

  constructor(id: number, title: string, isDefault: boolean, description: string,
    rank: number, createdAt: number, updatedAt: number) {
    this.id = id;
    this.title = title;
    this.description = description;
    this.isDefault = isDefault;
    this.rank = rank;
    this.createdAt = createdAt;
    this.updatedAt = updatedAt;
  }

  /** The implicit collection is protected: it is never deletable. */
  isDeletable(): boolean {
    return !this.isDefault;
  }
}

/** A collection together with the membership rows that are projected as active. */
export class RoomListWithPages {
  readonly list: RoomListEntity;
  readonly pages: ReadingListPageEntity[];

  constructor(list: RoomListEntity, pages: ReadingListPageEntity[]) {
    this.list = list;
    this.pages = pages;
  }

  get articleCount(): number {
    return this.pages.length;
  }
}

export class ReadingListPageEntity {
  readonly id: number;
  readonly listId: number;
  readonly pageTitle: PageTitle;
  status: string;
  readonly addedAt: number;
  updatedAt: number;

  constructor(id: number, listId: number, pageTitle: PageTitle, status: string,
    addedAt: number, updatedAt: number) {
    this.id = id;
    this.listId = listId;
    this.pageTitle = pageTitle;
    this.status = status && status.length > 0 ? status : STATUS_ACTIVE;
    this.addedAt = addedAt;
    this.updatedAt = updatedAt;
  }

  get isActive(): boolean {
    return this.status === STATUS_ACTIVE;
  }

  get isQueuedForDeletion(): boolean {
    return this.status === STATUS_QUEUE_FOR_DELETE;
  }

  get identity(): string {
    return this.pageTitle.identity;
  }
}

export function isDefaultCollectionTitle(title: string): boolean {
  return title === DEFAULT_COLLECTION_TITLE;
}

export { STATUS_ACTIVE, STATUS_QUEUE_FOR_DELETE };

/**
 * Observable presentation model of the Saved surface.
 *
 * Everything the page renders is derived from the reading list tables; this file
 * only describes the shapes that are handed to the UI layer.
 */
import { PageTitle } from './PageTitle';
import { EMPTY_STATE_NONE, FEEDBACK_ACTION_DISMISS, FEEDBACK_SEVERITY_INFO } from './SavedConstants';

/**
 * One row of the All articles tab.
 *
 * A row is a *logical* article: `id` is the identity of the representative
 * membership row and `collections` holds every collection that currently holds
 * the article, including the default collection.
 */
export class SavedArticleRow {
  id: number;
  article: string;
  language: string;
  apiTitle: string;
  displayTitle: string;
  collections: string[];
  collectionCount: number;
  onlyInDefaultCollection: boolean;
  isOffline: boolean;
  /** -1 when no download is in flight, otherwise a 0..1 progress fraction. */
  downloadProgress: number;
  selected: boolean;
  queuedForDeletion: boolean;

  constructor(id: number, pageTitle: PageTitle, collections: string[], onlyInDefaultCollection: boolean) {
    this.id = id;
    this.article = pageTitle.identity;
    this.language = pageTitle.languageCode;
    this.apiTitle = pageTitle.apiTitle;
    this.displayTitle = pageTitle.displayTitle;
    this.collections = collections;
    this.collectionCount = collections.length;
    this.onlyInDefaultCollection = onlyInDefaultCollection;
    this.isOffline = false;
    this.downloadProgress = -1;
    this.selected = false;
    this.queuedForDeletion = false;
  }
}

/** One row of the Collections tab. The default collection is never listed. */
export class SavedCollectionRow {
  id: number;
  title: string;
  description: string;
  isDefault: boolean;
  deletable: boolean;
  articleCount: number;
  offlineArticleCount: number;
  selected: boolean;
  queuedForDeletion: boolean;

  constructor(id: number, title: string, description: string, isDefault: boolean, articleCount: number) {
    this.id = id;
    this.title = title;
    this.description = description;
    this.isDefault = isDefault;
    this.deletable = !isDefault;
    this.articleCount = articleCount;
    this.offlineArticleCount = 0;
    this.selected = false;
    this.queuedForDeletion = false;
  }
}

/** A collection entry inside the save-article sheet. */
export class SaveArticleCollectionOption {
  id: number;
  title: string;
  isDefault: boolean;
  checked: boolean;
  /** The option cannot be toggled on because a limit is already reached. */
  disabled: boolean;
  limitReason: string;

  constructor(id: number, title: string, isDefault: boolean, checked: boolean) {
    this.id = id;
    this.title = title;
    this.isDefault = isDefault;
    this.checked = checked;
    this.disabled = false;
    this.limitReason = '';
  }
}

/**
 * State of the sheet that is opened after a reader taps "Save" on an article.
 * Opening the sheet always guarantees the article is saved.
 */
export class SaveArticleSheetState {
  visible: boolean;
  article: string;
  language: string;
  apiTitle: string;
  displayTitle: string;
  isSaved: boolean;
  collections: SaveArticleCollectionOption[];
  /** True while the destructive "remove from every collection" ask is pending. */
  pendingConfirmation: boolean;
  /** Non default collections that would lose the article when confirming. */
  confirmationCollections: string[];
  creatingCollection: boolean;
  newCollectionTitle: string;
  limitMessage: string;

  constructor(pageTitle: PageTitle) {
    this.visible = true;
    this.article = pageTitle.identity;
    this.language = pageTitle.languageCode;
    this.apiTitle = pageTitle.apiTitle;
    this.displayTitle = pageTitle.displayTitle;
    this.isSaved = false;
    this.collections = [];
    this.pendingConfirmation = false;
    this.confirmationCollections = [];
    this.creatingCollection = false;
    this.newCollectionTitle = '';
    this.limitMessage = '';
  }

  /** Collections that hold the article right now. */
  checkedCollectionTitles(): string[] {
    const titles: string[] = [];
    for (let index = 0; index < this.collections.length; index++) {
      if (this.collections[index].checked) {
        titles.push(this.collections[index].title);
      }
    }
    return titles;
  }
}

export class SavedFeedbackState {
