/**
 * Reading list storage.
 *
 * This is the offline cache that backs the Saved experience. It keeps the two
 * relational tables the feature is built on (collections and article
 * memberships) and publishes a change flow so that every derived query
 * re-projects itself. Writes always go through the DAOs, never through the UI.
 */
import { Flow } from './Flow';
import { PageTitle } from '../model/PageTitle';
import {
  ReadingListPageEntity,
  RoomListEntity,
  RoomListWithPages,
  STATUS_ACTIVE,
  STATUS_DELETED,
  STATUS_QUEUE_FOR_DELETE,
  isProjectedStatus
} from '../model/Entities';

export class ReadingListDatabase {
  private lists: RoomListEntity[] = [];
  private pages: ReadingListPageEntity[] = [];
  private nextListId: number = 1;
  private nextPageId: number = 1;
  private clock: number = 0;
  private readonly changes: Flow<number> = new Flow<number>(0);
  private revision: number = 0;

  constructor() {
    this.nextListId = 1;
    this.nextPageId = 1;
  }

  /* ---------------------------------------------------------------------- */
  /* Change notification                                                     */
  /* ---------------------------------------------------------------------- */

  /** Emits an increasing revision whenever a table is mutated. */
  changeFlow(): Flow<number> {
    return this.changes;
  }

  private touch(): void {
    this.revision = this.revision + 1;
    this.changes.emit(this.revision);
  }

  private tick(): number {
    this.clock = this.clock + 1;
    return this.clock;
  }

  /* ---------------------------------------------------------------------- */
  /* Reads                                                                   */
  /* ---------------------------------------------------------------------- */

  allLists(): RoomListEntity[] {
    return this.lists;
  }

  allPages(): ReadingListPageEntity[] {
    return this.pages;
  }

  listById(listId: number): RoomListEntity | undefined {
    for (let index = 0; index < this.lists.length; index++) {
      if (this.lists[index].id === listId) {
        return this.lists[index];
      }
    }
    return undefined;
  }

  listByTitle(title: string): RoomListEntity | undefined {
    for (let index = 0; index < this.lists.length; index++) {
      if (this.lists[index].title === title) {
        return this.lists[index];
      }
    }
    return undefined;
  }

  defaultList(): RoomListEntity | undefined {
    for (let index = 0; index < this.lists.length; index++) {
      if (this.lists[index].isDefault) {
        return this.lists[index];
      }
    }
    return undefined;
  }

  /** Every membership row, including rows queued for deletion. */
  pagesForList(listId: number): ReadingListPageEntity[] {
    const result: ReadingListPageEntity[] = [];
    for (let index = 0; index < this.pages.length; index++) {
      if (this.pages[index].listId === listId) {
        result.push(this.pages[index]);
      }
    }
    return result;
  }

  /** Membership rows that are projected to the UI for a collection. */
  activePagesForList(listId: number): ReadingListPageEntity[] {
    const result: ReadingListPageEntity[] = [];
    const rows = this.pagesForList(listId);
    for (let index = 0; index < rows.length; index++) {
      if (rows[index].isActive) {
        result.push(rows[index]);
      }
    }
    return result;
  }

  pageById(pageId: number): ReadingListPageEntity | undefined {
    for (let index = 0; index < this.pages.length; index++) {
      if (this.pages[index].id === pageId) {
        return this.pages[index];
      }
    }
    return undefined;
  }

  membership(listId: number, identity: string): ReadingListPageEntity | undefined {
    for (let index = 0; index < this.pages.length; index++) {
      const row = this.pages[index];
      if (row.listId === listId && row.identity === identity) {
        return row;
      }
    }
    return undefined;
  }

  /** Collections that currently project an article, ignoring default flag. */
  collectionTitlesOf(identity: string): string[] {
    const titles: string[] = [];
    for (let index = 0; index < this.pages.length; index++) {
      const row = this.pages[index];
      if (row.identity === identity && row.isActive) {
        const list = this.listById(row.listId);
        if (list !== undefined && titles.indexOf(list.title) < 0) {
          titles.push(list.title);
        }
      }
    }
    return titles;
  }

  /**
   * Collections holding an article. A default collection always sorts first so
   * that "only in the default collection" can be decided from a stable prefix.
   */
  sortedCollectionTitlesOf(identity: string): string[] {
    const titles = this.collectionTitlesOf(identity);
    const ordered: string[] = [];
    for (let index = 0; index < titles.length; index++) {
      const list = this.listByTitle(titles[index]);
      if (list !== undefined && list.isDefault) {
        ordered.push(titles[index]);
      }
    }
    for (let index = 0; index < titles.length; index++) {
      if (ordered.indexOf(titles[index]) < 0) {
        ordered.push(titles[index]);
      }
    }
    return ordered;
  }

  /**
   * The full set of projected collections, each with its active pages.
   * Membership rows with `STATUS_QUEUE_FOR_DELETE` are excluded here, which is
   * why an article pending deletion disappears from the Saved surface before
   * the deletion is confirmed.
   */
  listsWithPages(): RoomListWithPages[] {
    const projected: RoomListWithPages[] = [];
    for (let index = 0; index < this.lists.length; index++) {
      const list = this.lists[index];
      projected.push(new RoomListWithPages(list, this.activePagesForList(list.id)));
    }
    return projected;
  }

  countLists(): number {
    return this.lists.length;
  }

  countUserLists(): number {
    let total = 0;
    for (let index = 0; index < this.lists.length; index++) {
      if (!this.lists[index].isDefault) {
        total = total + 1;
      }
    }
    return total;
  }

  /* ---------------------------------------------------------------------- */
  /* Writes                                                                  */
  /* ---------------------------------------------------------------------- */

  insertList(list: RoomListEntity): RoomListEntity {
    this.lists.push(list);
    if (list.id >= this.nextListId) {
      this.nextListId = list.id + 1;
    }
    this.touch();
    return list;
  }

  insertPage(page: ReadingListPageEntity): ReadingListPageEntity {
    this.pages.push(page);
    if (page.id >= this.nextPageId) {
      this.nextPageId = page.id + 1;
    }
    this.touch();
    return page;
  }

  setPageStatus(pageId: number, status: string): ReadingListPageEntity | undefined {
    const page = this.pageById(pageId);
    if (page === undefined) {
      return undefined;
    }
    page.status = status;
    page.updatedAt = this.tick();
    this.touch();
    return page;
  }

  /** Permanently removes membership rows by identifier. */
  hardDeletePages(pageIds: number[]): number {
    let removed = 0;
    for (let index = this.pages.length - 1; index >= 0; index--) {
      if (pageIds.indexOf(this.pages[index].id) >= 0) {
        this.pages.splice(index, 1);
        removed = removed + 1;
      }
    }
    if (removed > 0) {
      this.touch();
    }
    return removed;
  }

  /** Moves every membership row of an article into the queue-for-delete status. */
  queuePagesForIdentity(identity: string): number {
    let queued = 0;
    for (let index = 0; index < this.pages.length; index++) {
      const page = this.pages[index];
      if (page.identity === identity && page.status !== STATUS_DELETED) {
        page.status = STATUS_QUEUE_FOR_DELETE;
        page.updatedAt = this.tick();
        queued = queued + 1;
      }
    }
    if (queued > 0) {
      this.touch();
    }
    return queued;
  }

  /** Undo: brings queued membership rows back as active. */
  restoreQueuedPages(pageIds: number[]): number {
    let restored = 0;
    for (let index = 0; index < this.pages.length; index++) {
      const page = this.pages[index];
      if (pageIds.indexOf(page.id) >= 0 && page.status === STATUS_QUEUE_FOR_DELETE) {
        page.status = STATUS_ACTIVE;
        page.updatedAt = this.tick();
        restored = restored + 1;
      }
    }
    if (restored > 0) {
      this.touch();
    }
    return restored;
  }

  queuedPages(): ReadingListPageEntity[] {
    const queued: ReadingListPageEntity[] = [];
    for (let index = 0; index < this.pages.length; index++) {
      if (this.pages[index].isQueuedForDeletion) {
        queued.push(this.pages[index]);
      }
    }
    return queued;
  }

  /** Removes a collection and every membership row it owns. */
  deleteListCascade(listId: number): RoomListEntity | undefined {
    const list = this.listById(listId);
    if (list === undefined) {
      return undefined;
    }
    for (let index = this.pages.length - 1; index >= 0; index--) {
      if (this.pages[index].listId === listId) {
        this.pages.splice(index, 1);
      }
    }
    for (let index = this.lists.length - 1; index >= 0; index--) {
      if (this.lists[index].id === listId) {
        this.lists.splice(index, 1);
      }
    }
    this.touch();
    return list;
  }

  /** Removes a collection but keeps its membership rows for undo. */
  queueListForDeletion(listId: number): RoomListEntity | undefined {
    const list = this.listById(listId);
    if (list === undefined) {
      return undefined;
    }
    for (let index = 0; index < this.pages.length; index++) {
      const page = this.pages[index];
      if (page.listId === listId && page.status !== STATUS_DELETED) {
        page.status = STATUS_QUEUE_FOR_DELETE;
        page.updatedAt = this.tick();
      }
    }
    this.touch();
    return list;
  }

  /** Undo for collection deletion: the collection and its rows come back. */
  restoreList(listId: number): RoomListEntity | undefined {
    const list = this.listById(listId);
    if (list === undefined) {
      return undefined;
    }
    for (let index = 0; index < this.pages.length; index++) {
      const page = this.pages[index];
      if (page.listId === listId && page.status === STATUS_QUEUE_FOR_DELETE) {
        page.status = STATUS_ACTIVE;
        page.updatedAt = this.tick();
      }
    }
    this.touch();
    return list;
  }

  reserveListId(): number {
    return this.nextListId++;
  }

  reservePageId(): number {
    return this.nextPageId++;
  }

  nextTimestamp(): number {
    return this.tick();
  }

  /* ---------------------------------------------------------------------- */
  /* Diagnostics                                                             */
  /* ---------------------------------------------------------------------- */

  isProjecting(page: ReadingListPageEntity): boolean {
    return isProjectedStatus(page.status);
  }
}

export { PageTitle };

/**
 * Collection and article limits.
 *
 * Limits are a product rule, not a transport concern: when one of them is hit
 * the requested addition is refused, the reason is surfaced to the reader and
 * the existing memberships are left untouched.
 */
import {
  LIMIT_MESSAGE_COLLECTION_COUNT,
  LIMIT_MESSAGE_COLLECTION_FULL,
  LIMIT_REASON_COLLECTION_COUNT,
  LIMIT_REASON_COLLECTION_FULL,
  MAX_ARTICLES_PER_COLLECTION,
  MAX_COLLECTIONS_PER_USER
} from './SavedConstants';

export class LimitDecision {
  readonly allowed: boolean;
  readonly reason: string;
  readonly message: string;

  constructor(allowed: boolean, reason: string, message: string) {
    this.allowed = allowed;
    this.reason = reason;
    this.message = message;
  }
}

export class SavedLimitPolicy {
  /** Guard for "add this article to that collection". */
  static canAddArticle(currentArticleCount: number): LimitDecision {
    if (currentArticleCount >= MAX_ARTICLES_PER_COLLECTION) {
      return new LimitDecision(false, LIMIT_REASON_COLLECTION_FULL, LIMIT_MESSAGE_COLLECTION_FULL);
    }
    return new LimitDecision(true, '', '');
  }

  /** Guard for "create another collection". */
  static canCreateCollection(currentUserCollectionCount: number): LimitDecision {
    if (currentUserCollectionCount >= MAX_COLLECTIONS_PER_USER) {
      return new LimitDecision(false, LIMIT_REASON_COLLECTION_COUNT, LIMIT_MESSAGE_COLLECTION_COUNT);
    }
    return new LimitDecision(true, '', '');
  }

  static maxArticlesPerCollection(): number {
    return MAX_ARTICLES_PER_COLLECTION;
  }

  static maxCollectionsPerUser(): number {
    return MAX_COLLECTIONS_PER_USER;
  }
}

/**
 * Collection (Room list) DAO.
 *
 * Exposes the reactive projection used by the page plus the semantic writes of
 * the Collections tab. Every write re-notifies the change flow, which is what
 * makes both visible surfaces update from a single database change.
 */
import { Flow } from './Flow';
import { ReadingListDatabase } from './ReadingListDatabase';
import { RoomListEntity, RoomListWithPages } from '../model/Entities';
import { SavedLimitPolicy } from '../model/SavedLimits';
import { DEFAULT_COLLECTION_TITLE } from '../model/SavedConstants';

export class CollectionCreation {
  readonly created: RoomListEntity | undefined;
  readonly reason: string;
  readonly message: string;

  constructor(created: RoomListEntity | undefined, reason: string, message: string) {
    this.created = created;
    this.reason = reason;
    this.message = message;
  }
}

export class ReadingListsDao {
  private readonly database: ReadingListDatabase;
  private readonly listsWithPages: Flow<RoomListWithPages[]>;

  constructor(database: ReadingListDatabase) {
    this.database = database;
    this.listsWithPages = new Flow<RoomListWithPages[]>(this.project());
    this.database.changeFlow().collect((): void => {
      this.listsWithPages.emit(this.project());
    });
  }

  /**
   * Reactive stream of every collection together with the membership rows that
   * are projected as active.
   */
  observeListsWithPages(): Flow<RoomListWithPages[]> {
    return this.listsWithPages;
  }

  private project(): RoomListWithPages[] {
    return this.database.listsWithPages();
  }

  listById(listId: number): RoomListEntity | undefined {
    return this.database.listById(listId);
  }

  listByTitle(title: string): RoomListEntity | undefined {
    return this.database.listByTitle(title);
  }

  /** The protected default collection; created on demand. */
  defaultList(): RoomListEntity {
    const existing = this.database.defaultList();
    if (existing !== undefined) {
      return existing;
    }
    const now = this.database.nextTimestamp();
    return this.database.insertList(
      new RoomListEntity(this.database.reserveListId(), DEFAULT_COLLECTION_TITLE, true, '', 0, now, now));
  }

  countUserCollections(): number {
    return this.database.countUserLists();
  }

  /** User created collections only: the default collection is never listed. */
  userCollections(): RoomListEntity[] {
    const result: RoomListEntity[] = [];
    const projected = this.listsWithPages.getValue();
    for (let index = 0; index < projected.length; index++) {
      if (!projected[index].list.isDefault) {
        result.push(projected[index].list);
      }
    }
    return result;
  }

  /** Creates a user collection, honouring the per-account collection limit. */
  createCollection(title: string, description: string): CollectionCreation {
    const trimmed = title.trim();
    if (trimmed.length === 0) {
      return new CollectionCreation(undefined, 'EMPTY_TITLE', '');
    }
    if (this.listByTitle(trimmed) !== undefined) {
      return new CollectionCreation(undefined, 'DUPLICATE_TITLE', '');
    }
    const decision = SavedLimitPolicy.canCreateCollection(this.countUserCollections());
    if (!decision.allowed) {
      return new CollectionCreation(undefined, decision.reason, decision.message);
    }
    const now = this.database.nextTimestamp();
    const rank = this.countUserCollections() + 1;
    const created = this.database.insertList(
      new RoomListEntity(this.database.reserveListId(), trimmed, false, description, rank, now, now));
    return new CollectionCreation(created, '', '');
  }

  renameCollection(listId: number, title: string): boolean {
    const list = this.listById(listId);
    if (list === undefined || list.isDefault) {
      return false;
    }
    const trimmed = title.trim();
    if (trimmed.length === 0) {
      return false;
    }
    list.title = trimmed;
    list.updatedAt = this.database.nextTimestamp();
    this.notifyRename();
    return true;
  }

  private notifyRename(): void {
    this.listsWithPages.emit(this.project());
  }

  /** Queues a collection for deletion; the default collection is protected. */
  queueCollectionForDeletion(listId: number): RoomListEntity | undefined {
    const list = this.listById(listId);
    if (list === undefined || !list.isDeletable()) {
      return undefined;
    }
    return this.database.queueListForDeletion(listId);
  }

  /** Hard removal; used once the undo window elapsed. */
  deleteCollection(listId: number): RoomListEntity | undefined {
    const list = this.listById(listId);
    if (list === undefined || !list.isDeletable()) {
      return undefined;
    }
    return this.database.deleteListCascade(listId);
  }

  /** Undo path for a queued collection deletion. */
  restoreCollection(listId: number): RoomListEntity | undefined {
    const list = this.listById(listId);
    if (list === undefined || !list.isDeletable()) {
      return undefined;
    }
    return this.database.restoreList(listId);
  }
}

/**
 * Membership (article) DAO.
 *
 * A membership row links one article to one collection. The DAO is also where
 * the logical-article aggregation lives: the All articles tab must show every
 * logical article once while keeping the complete set of containing
 * collections, so aggregation happens on read and never changes membership.
 */
import { Flow } from './Flow';
import { ReadingListDatabase } from './ReadingListDatabase';
import { ReadingListsDao } from './ReadingListsDao';
import { PageTitle } from '../model/PageTitle';
import { ReadingListPageEntity } from '../model/Entities';
import { SavedLimitPolicy } from '../model/SavedLimits';
import { RoomListEntity, STATUS_ACTIVE } from '../model/Entities';

/** Deduplicated view of one saved article plus all of its memberships. */
export class SavedArticleRecord {
  /** Identity of the membership row that represents this logical article. */
  readonly rowId: number;
  readonly pageTitle: PageTitle;
  readonly collections: string[];
  readonly addedAt: number;
  readonly updatedAt: number;

  constructor(rowId: number, pageTitle: PageTitle, collections: string[], addedAt: number, updatedAt: number) {
    this.rowId = rowId;
    this.pageTitle = pageTitle;
    this.collections = collections;
    this.addedAt = addedAt;
    this.updatedAt = updatedAt;
  }

  get identity(): string {
    return this.pageTitle.identity;
  }

  /** True when the default collection is the only container of the article. */
  onlyInDefaultCollection(defaultTitle: string): boolean {
    if (this.collections.length !== 1) {
      return false;
    }
    return this.collections[0] === defaultTitle;
  }

  isInNamedCollection(defaultTitle: string): boolean {
    for (let index = 0; index < this.collections.length; index++) {
      if (this.collections[index] !== defaultTitle) {
        return true;
      }
    }
    return false;
  }
}

export class MembershipChange {
  readonly applied: boolean;
  readonly reason: string;
  readonly message: string;
  readonly page: ReadingListPageEntity | undefined;

  constructor(applied: boolean, reason: string, message: string, page: ReadingListPageEntity | undefined) {
    this.applied = applied;
    this.reason = reason;
    this.message = message;
    this.page = page;
  }
}

export class ReadingListPagesDao {
  private readonly database: ReadingListDatabase;
  private readonly listsDao: ReadingListsDao;
  private readonly activePages: Flow<ReadingListPageEntity[]>;

  constructor(database: ReadingListDatabase, listsDao: ReadingListsDao) {
    this.database = database;
    this.listsDao = listsDao;
    this.activePages = new Flow<ReadingListPageEntity[]>(this.projectActive());
    this.database.changeFlow().collect((): void => {
      this.activePages.emit(this.projectActive());
    });
  }

  /** Reactive stream of the membership rows that are projected as active. */
  observeActivePages(): Flow<ReadingListPageEntity[]> {
    return this.activePages;
  }

  private projectActive(): ReadingListPageEntity[] {
    const all = this.database.allPages();
    const active: ReadingListPageEntity[] = [];
    for (let index = 0; index < all.length; index++) {
      if (all[index].isActive) {
        active.push(all[index]);
      }
    }
    return active;
  }

  /** The protected default collection. */
  defaultList(): RoomListEntity {
    return this.listsDao.defaultList();
  }

  defaultTitle(): string {
    return this.defaultList().title;
  }

  /* ---------------------------------------------------------------------- */
  /* Aggregation                                                             */
  /* ---------------------------------------------------------------------- */

  /**
   * Deduplicates membership rows into logical articles keyed by wiki language
   * plus API title. The representative row is the membership inside the default
   * collection when present, which keeps the row id stable while the reader
   * adds the article to further collections.
   */
  logicalArticles(): SavedArticleRecord[] {
    const pages = this.projectActive();
    const identities: string[] = [];
    const members: SavedArticleRecord[] = [];
    const indexes = new Map<string, number>();

    for (let index = 0; index < pages.length; index++) {
      const page = pages[index];
      const identity = page.identity;
      const list = this.database.listById(page.listId);
      const title = list !== undefined ? list.title : '';
      const existing = indexes.has(identity) ? indexes.get(identity) : -1;
      if (existing < 0) {
        indexes.set(identity, members.length);
        members.push(new SavedArticleRecord(page.id, page.pageTitle, [title], page.addedAt, page.updatedAt));
      } else {
        const record = members[existing];
        if (record.collections.indexOf(title) < 0) {
          record.collections.push(title);
        }
        if (page.updatedAt > record.updatedAt) {
          record.updatedAt = page.updatedAt;
        }
      }
    }

    const defaultList = this.database.defaultList();
    const defaultId = defaultList !== undefined ? defaultList.id : -1;
    for (let index = 0; index < members.length; index++) {
      const identity = members[index].identity;
      const defaultRow = this.database.membership(defaultId, identity);
      if (defaultRow !== undefined && defaultRow.isActive) {
        members[index] = new SavedArticleRecord(
          defaultRow.id, members[index].pageTitle, members[index].collections,
          members[index].addedAt, members[index].updatedAt);
      }
    }

    for (let index = 0; index < members.length; index++) {
      members[index].collections = this.database.sortedCollectionTitlesOf(members[index].identity);
    }
    return members;
  }

  membershipsOf(identity: string): string[] {
    return this.database.sortedCollectionTitlesOf(identity);
  }

  nonDefaultMembershipsOf(identity: string): string[] {
    const defaultTitle = this.defaultTitle();
    const all = this.membershipsOf(identity);
    const result: string[] = [];
    for (let index = 0; index < all.length; index++) {
      if (all[index] !== defaultTitle) {
        result.push(all[index]);
      }
    }
    return result;
  }

  isSaved(identity: string): boolean {
    return this.membershipsOf(identity).length > 0;
  }

  queuedPageIdsFor(identities: string[]): number[] {
    const queued: number[] = [];
    const pages = this.database.queuedPages();
    for (let index = 0; index < pages.length; index++) {
      if (identities.indexOf(pages[index].identity) >= 0) {
        queued.push(pages[index].id);
      }
    }
    return queued;
  }

  /* ---------------------------------------------------------------------- */
  /* Writes                                                                  */
  /* ---------------------------------------------------------------------- */

  /**
   * Guarantees the article sits in the default collection, which is what makes
   * "Save" idempotent. Returns the membership row.
   */
  saveToDefaultCollection(pageTitle: PageTitle): MembershipChange {
    const defaultList = this.defaultList();
    const existing = this.database.membership(defaultList.id, pageTitle.identity);
    if (existing !== undefined && existing.isActive) {
      return new MembershipChange(true, '', '', existing);
    }
    if (existing !== undefined) {
      const revived = this.database.setPageStatus(existing.id, STATUS_ACTIVE);
      return new MembershipChange(revived !== undefined, '', '', revived);
    }
    const decision = SavedLimitPolicy.canAddArticle(this.database.activePagesForList(defaultList.id).length);
    if (!decision.allowed) {
      return new MembershipChange(false, decision.reason, decision.message, undefined);
    }
    const now = this.database.nextTimestamp();
    const page = this.database.insertPage(new ReadingListPageEntity(
      this.database.reservePageId(), defaultList.id, pageTitle, STATUS_ACTIVE, now, now));
    return new MembershipChange(true, '', '', page);
  }

  /** Adds an article to a specific collection, honouring collection limits. */
  addToCollection(listId: number, pageTitle: PageTitle): MembershipChange {
    const list = this.database.listById(listId);
    if (list === undefined) {
      return new MembershipChange(false, 'MISSING_COLLECTION', '', undefined);
    }
    const existing = this.database.membership(listId, pageTitle.identity);
    if (existing !== undefined && existing.isActive) {
      return new MembershipChange(true, '', '', existing);
    }
    const decision = SavedLimitPolicy.canAddArticle(this.database.activePagesForList(listId).length);
    if (!decision.allowed) {
      return new MembershipChange(false, decision.reason, decision.message, undefined);
    }
    if (existing !== undefined) {
      const revived = this.database.setPageStatus(existing.id, STATUS_ACTIVE);
      return new MembershipChange(revived !== undefined, '', '', revived);
    }
    const now = this.database.nextTimestamp();
    const page = this.database.insertPage(new ReadingListPageEntity(
      this.database.reservePageId(), listId, pageTitle, STATUS_ACTIVE, now, now));
    return new MembershipChange(true, '', '', page);
  }

  /**
   * Adds or removes the article from a collection depending on its current
   * state. A collection that no longer exists is a no-op: the operation must
   * never fall back to another collection.
   */
  toggleCollection(listId: number, pageTitle: PageTitle): MembershipChange {
    const list = this.database.listById(listId);
    if (list === undefined) {
      return new MembershipChange(false, 'MISSING_COLLECTION', '', undefined);
    }
    const existing = this.database.membership(listId, pageTitle.identity);
    if (existing !== undefined && existing.isActive) {
      const removed = this.database.hardDeletePages([existing.id]);
      return new MembershipChange(removed > 0, 'REMOVED', '', existing);
    }
    if (existing !== undefined) {
      const revived = this.database.setPageStatus(existing.id, STATUS_ACTIVE);
      return new MembershipChange(revived !== undefined, '', '', revived);
    }
    return this.addToCollection(listId, pageTitle);
  }

  /** Removes a single membership row. */
  removeFromCollection(listId: number, identity: string): boolean {
    const existing = this.database.membership(listId, identity);
    if (existing === undefined) {
      return false;
    }
    return this.database.hardDeletePages([existing.id]) > 0;
  }

  /** Unsave: drops every membership of the article in one write. */
  removeEveryMembership(identity: string): number {
    let removed = 0;
    const rows = this.database.allPages();
    const ids: number[] = [];
    for (let index = 0; index < rows.length; index++) {
      if (rows[index].identity === identity && rows[index].status !== 'STATUS_DELETED') {
        ids.push(rows[index].id);
      }
    }
    removed = this.database.hardDeletePages(ids);
    return removed;
  }

  /** Queues every membership of the given articles for deletion. */
  queueForDeletion(identities: string[]): number[] {
    const queued: number[] = [];
    for (let index = 0; index < identities.length; index++) {
      this.database.queuePagesForIdentity(identities[index]);
      const ids = this.database.queuedPages();
      for (let inner = 0; inner < ids.length; inner++) {
        if (ids[inner].identity === identities[index] && queued.indexOf(ids[inner].id) < 0) {
          queued.push(ids[inner].id);
        }
      }
    }
    return queued;
  }

  /** Undo for a queued deletion. */
  restoreQueued(pageIds: number[]): number {
    return this.database.restoreQueuedPages(pageIds);
  }

  activeArticleCountFor(listId: number): number {
    return this.database.activePagesForList(listId).length;
  }
}

/**
 * Persisted preferences of the Saved surface.
 *
 * Everything the reader expects to survive a restart lives here: the sort mode
 * of each view (persisted independently), the last visible tab, whether
 * reading list synchronisation is enabled, and the durable snapshot of the
 * offline reading list cache.
 */
import { common } from '@kit.AbilityKit';
import { preferences } from '@kit.ArkData';
import {
  PREFERENCE_ARTICLE_SORT_MODE,
  PREFERENCE_COLLECTION_SORT_MODE,
  PREFERENCE_DATABASE_SNAPSHOT,
  PREFERENCE_LAST_TAB,
  PREFERENCE_STORE_NAME,
  PREFERENCE_SYNC_ENABLED,
  SORT_BY_NAME_ASC
} from '../model/SavedConstants';

export class SavedPreferences {
  private store: preferences.Preferences;
  private cache: Map<string, string>;

  private constructor(store: preferences.Preferences) {
    this.store = store;
    this.cache = new Map<string, string>();
  }

  static async create(context: common.UIAbilityContext, storeName: string): Promise<SavedPreferences> {
    const store = await preferences.getPreferences(context, storeName);
    const holder = new SavedPreferences(store);
    await holder.warmUp();
    return holder;
  }

  static defaultStoreName(): string {
    return PREFERENCE_STORE_NAME;
  }

  private async warmUp(): Promise<void> {
    const defaults: string[] = [
      PREFERENCE_ARTICLE_SORT_MODE,
      PREFERENCE_COLLECTION_SORT_MODE,
      PREFERENCE_LAST_TAB,
      PREFERENCE_SYNC_ENABLED,
      PREFERENCE_DATABASE_SNAPSHOT
    ];
    for (let index = 0; index < defaults.length; index++) {
      const key = defaults[index];
      const value = await this.store.get(key, '');
      if (typeof value === 'string') {
        this.cache.set(key, value);
      }
    }
  }

  private read(key: string, fallback: string): string {
    const cached = this.cache.get(key);
    return cached !== undefined ? cached : fallback;
  }

  private async write(key: string, value: string): Promise<void> {
    this.cache.set(key, value);
    await this.store.put(key, value);
    await this.store.flush();
  }

  /* -------------------------------------------------------------------- */
  /* Sort modes (independent per view)                                      */
  /* -------------------------------------------------------------------- */

  articleSortMode(): number {
    return this.readNumber(PREFERENCE_ARTICLE_SORT_MODE, SORT_BY_NAME_ASC);
  }

  setArticleSortMode(mode: number): Promise<void> {
    return this.write(PREFERENCE_ARTICLE_SORT_MODE, String(mode));
  }

  collectionSortMode(): number {
    return this.readNumber(PREFERENCE_COLLECTION_SORT_MODE, SORT_BY_NAME_ASC);
  }

  setCollectionSortMode(mode: number): Promise<void> {
    return this.write(PREFERENCE_COLLECTION_SORT_MODE, String(mode));
  }

  private readNumber(key: string, fallback: number): number {
    const raw = this.read(key, '');
    if (raw.length === 0) {
      return fallback;
    }
    const parsed = Number(raw);
    if (isNaN(parsed)) {
      return fallback;
    }
    return parsed;
  }

  /* -------------------------------------------------------------------- */
  /* Tab + sync preference                                                  */
  /* -------------------------------------------------------------------- */

  lastTab(): string {
    return this.read(PREFERENCE_LAST_TAB, '');
  }

  setLastTab(tab: string): Promise<void> {
    return this.write(PREFERENCE_LAST_TAB, tab);
  }

  isSyncEnabled(): boolean {
    return this.read(PREFERENCE_SYNC_ENABLED, 'true') === 'true';
  }

  setSyncEnabled(enabled: boolean): Promise<void> {
    return this.write(PREFERENCE_SYNC_ENABLED, enabled ? 'true' : 'false');
  }

  /* -------------------------------------------------------------------- */
  /* Offline cache snapshot                                                 */
  /* -------------------------------------------------------------------- */

  loadSnapshot(): string {
    return this.read(PREFERENCE_DATABASE_SNAPSHOT, '');
  }

  persistSnapshot(serialised: string): Promise<void> {
    return this.write(PREFERENCE_DATABASE_SNAPSHOT, serialised);
  }

  async clear(): Promise<void> {
    this.cache = new Map<string, string>();
    await this.store.clear();
    await this.store.flush();
  }

  /* -------------------------------------------------------------------- */
  /* Snapshot mirror used by the persistence projection                    */
  /* -------------------------------------------------------------------- */

  /** Serialised view of everything this class persists. */
  snapshotValues(): Map<string, string> {
    return new Map<string, string>(this.cache);
  }
}

/**
 * External boundaries of the Saved feature.
 *
 * HTTP, reading list synchronisation, analytics and file services live here and
 * nowhere else. The rest of the feature only ever sees the typed results below,
 * which is what makes it possible to reason about offline devices, failing
 * requests and interrupted synchronisations without leaking transport concerns
 * into the state reduction.
 *
 * Every call is published on the injected leaf sink so the surrounding
 * application can observe the traffic; the sink never decides behaviour.
 */
import { SavedEffect, SavedLeaf } from '../../integration/SavedPageIntegration';
import { PageTitle } from '../model/PageTitle';

export const LEAF_HTTP: string = 'http';
export const LEAF_SYNC: string = 'sync';
export const LEAF_ANALYTICS: string = 'analytics';
export const LEAF_FILE: string = 'file';

export const ROUTE_REDIRECT_METADATA: string = 'redirect/metadata';
export const ROUTE_READING_LIST_SYNC: string = 'readinglist/sync';
export const ROUTE_SHARED_COLLECTION: string = 'readinglist/shared';

export const OUTCOME_OK: string = 'ok';
export const OUTCOME_OFFLINE: string = 'offline';
export const OUTCOME_IO: string = 'error:io';
export const OUTCOME_HTTP: string = 'error:http';

export class HttpResult {
  readonly ok: boolean;
  readonly status: string;
  readonly body: string;
  readonly exception: string;

  constructor(ok: boolean, status: string, body: string, exception: string) {
    this.ok = ok;
    this.status = status;
    this.body = body;
    this.exception = exception;
  }
}

/** Canonical title of an article after redirect resolution. */
export class RedirectMetadata {
  readonly from: string;
  readonly to: string;

  constructor(from: string, to: string) {
    this.from = from;
    this.to = to;
  }
}

export class ReadingListSyncRequest {
  readonly force: boolean;
  readonly fromRefresh: boolean;
  readonly attempt: number;

  constructor(force: boolean, fromRefresh: boolean, attempt: number) {
    this.force = force;
    this.fromRefresh = fromRefresh;
    this.attempt = attempt;
  }
}

export class ReadingListSyncResponse {
  readonly completed: boolean;
  readonly exception: string;
  /** `true` when the remote side pushed changes before completing. */
  readonly applied: boolean;

  constructor(completed: boolean, exception: string, applied: boolean) {
    this.completed = completed;
    this.exception = exception;
    this.applied = applied;
  }
}

/**
 * Transport that knows how the network behaves right now. Outcomes are a
 * device/app level fact (offline, IO failure, HTTP error); the Saved feature
 * never assumes success.
 */
export class HttpTransport {
  private readonly outcomes: Map<string, string> = new Map<string, string>();
  private readonly bodies: Map<string, string> = new Map<string, string>();

  configure(route: string, outcome: string, body: string): void {
    this.outcomes.set(route, outcome);
    if (body.length > 0) {
      this.bodies.set(route, body);
    }
  }

  outcomeOf(route: string): string {
    const configured = this.outcomes.get(route);
    return configured !== undefined ? configured : OUTCOME_OK;
  }

  bodyOf(route: string): string {
    const configured = this.bodies.get(route);
    return configured !== undefined ? configured : '';
  }

  isHealthy(route: string): boolean {
    return this.outcomeOf(route) === OUTCOME_OK;
  }
}

export class SavedEnvironment {
  private readonly leaf: SavedLeaf;
  private readonly http: HttpTransport;

  constructor(leaf: SavedLeaf) {
    this.leaf = leaf;
    this.http = new HttpTransport();
  }

  configureRoute(route: string, outcome: string, body: string): void {
    this.http.configure(route, outcome, body);
  }

  isRouteHealthy(route: string): boolean {
    return this.http.isHealthy(route);
  }

  /**
   * Resolves the canonical title of an article.
   *
   * When the device is offline or the request fails the caller receives
   * `undefined` and keeps the original language and API title; a failed lookup
   * must never prevent the article from being saved.
   */
  async resolveRedirectMetadata(pageTitle: PageTitle): Promise<RedirectMetadata | undefined> {
    const route = ROUTE_REDIRECT_METADATA;
    const outcome = this.http.outcomeOf(route);
    const body = this.http.bodyOf(route);
    if (outcome !== OUTCOME_OK) {
      await this.publish({
        name: 'resolveRedirectMetadata',
        leaf: LEAF_HTTP,
        status: 'error',
        exception: outcome,
        article: pageTitle.identity
      });
      return undefined;
    }
    const canonical = this.parseRedirectTarget(body, pageTitle);
    await this.publish({
      name: 'resolveRedirectMetadata',
      leaf: LEAF_HTTP,
      status: 'ok',
      article: pageTitle.identity
    });
    if (canonical.length === 0 || canonical === pageTitle.apiTitle) {
      return undefined;
    }
    return new RedirectMetadata(pageTitle.apiTitle, canonical);
  }

  private parseRedirectTarget(body: string, pageTitle: PageTitle): string {
    if (body.length === 0) {
      return '';
    }
    const parsed = JSON.parse(body) as RedirectTargetBody;
    if (parsed === undefined || parsed === null) {
      return '';
    }
    if (parsed.from === pageTitle.apiTitle && parsed.to !== undefined && parsed.to.length > 0) {
      return parsed.to;
    }
    return '';
  }

  /** Starts a reading list synchronisation round trip. */
  async startReadingListSync(request: ReadingListSyncRequest): Promise<ReadingListSyncResponse> {
    const outcome = this.http.outcomeOf(ROUTE_READING_LIST_SYNC);
    await this.publish({
      name: 'startReadingListSync',
      leaf: LEAF_SYNC,
      status: outcome === OUTCOME_OK ? 'started' : 'error',
      exception: outcome === OUTCOME_OK ? '' : outcome,
      force: request.force,
      fromRefresh: request.fromRefresh,
      attempt: request.attempt
    });
    if (outcome !== OUTCOME_OK) {
      return new ReadingListSyncResponse(false, outcome, false);
    }
    return new ReadingListSyncResponse(true, '', true);
  }

  /** Reports that the synchronisation finished, successfully or not. */
  async reportSyncEvent(completed: boolean, exception: string, surfaces: string[]): Promise<void> {
    await this.publish({
      name: 'readingListSyncEvent',
      leaf: LEAF_SYNC,
      status: completed ? 'completed' : 'failed',
      exception: exception,
      surfaces: surfaces
    });
  }

  async logEvent(name: string, surfaces: string[]): Promise<void> {
    await this.publish({ name: name, leaf: LEAF_ANALYTICS, status: 'ok', surfaces: surfaces });
  }

  async writeExportFile(fileName: string, content: string): Promise<HttpResult> {
    await this.publish({ name: 'writeExportFile', leaf: LEAF_FILE, status: 'ok', surface: fileName });
    return new HttpResult(true, '200', content.length, '');
  }

  /** Publishes one effect on the leaf sink. */
  async publish(effect: SavedEffect): Promise<void> {
    await this.leaf.emit(effect);
  }
}

interface RedirectTargetBody {
  from?: string;
  to?: string;
}

/**
 * Session state owned by the Saved feature.
 *
 * Login, logout, receipt of a shared collection and the reading list
 * synchronisation preference all feed this object, which in turn drives the
 * onboarding content and the eligibility of the pull-to-refresh action.
 */
import { SavedAccountState } from '../model/SavedUiState';

export class SavedSession {
  private readonly account: SavedAccountState;
  private syncEnabled: boolean;
  private sharedCollectionsReceived: number;
  private pendingSharedCollectionTitle: string;

  constructor() {
    this.account = new SavedAccountState();
    this.syncEnabled = true;
    this.sharedCollectionsReceived = 0;
    this.pendingSharedCollectionTitle = '';
  }

  snapshot(): SavedAccountState {
    return this.account;
  }

  isLoggedIn(): boolean {
    return this.account.isLoggedIn;
  }

  userName(): string {
    return this.account.userName;
  }

  /**
   * Synchronisation is only offered to a permanent, signed in account. A
   * signed out or temporary account has to be offered a login instead.
   */
  isSyncEligible(): boolean {
    return this.account.isSyncEligible();
  }

  isSyncEnabled(): boolean {
    return this.syncEnabled;
  }

  applySyncEnabled(enabled: boolean): void {
    this.syncEnabled = enabled;
  }

  /** Production login event; account eligibility is refreshed here. */
  applyLogin(userName: string, temporary: boolean): void {
    this.account.isLoggedIn = true;
    this.account.isTemporary = temporary;
    this.account.userName = userName;
  }

  applyLogout(): void {
    this.account.isLoggedIn = false;
    this.account.isTemporary = false;
    this.account.userName = '';
  }

  /** A collection shared by somebody else arrived from a deep link. */
  applySharedCollection(title: string): void {
    this.sharedCollectionsReceived = this.sharedCollectionsReceived + 1;
    this.pendingSharedCollectionTitle = title;
  }

  takeSharedCollection(): string {
    const title = this.pendingSharedCollectionTitle;
    this.pendingSharedCollectionTitle = '';
    return title;
  }

  sharedCollectionCount(): number {
    return this.sharedCollectionsReceived;
  }
}

/**
 * Offline availability and download progress of saved articles.
 *
 * The Saved surface reflects media state for the articles that are visible, so
 * this store keeps only the identities it was told about and lets the view model
 * project them onto rows.
 */
export const DOWNLOAD_IDLE: number = -1;

export class ArticleMediaStatus {
  private readonly offline: Map<string, boolean> = new Map<string, boolean>();
  private readonly progress: Map<string, number> = new Map<string, number>();

  setOffline(identity: string, available: boolean): void {
    this.offline.set(identity, available);
  }

  setDownloadProgress(identity: string, fraction: number): void {
    if (fraction < 0 || fraction >= 1) {
      this.progress.delete(identity);
      return;
    }
    this.progress.set(identity, fraction);
  }

  isOffline(identity: string): boolean {
    return this.offline.get(identity) === true;
  }

  downloadProgress(identity: string): number {
    const value = this.progress.get(identity);
    return value !== undefined ? value : DOWNLOAD_IDLE;
  }

  /** Drops entries for articles that are no longer visible anywhere. */
  retainOnly(identities: string[]): void {
    const stale: string[] = [];
    const offlineKeys = this.offline.keys();
    while (offlineKeys.hasNext()) {
      const key = offlineKeys.next().value as string;
      if (identities.indexOf(key) < 0) {
        stale.push(key);
      }
    }
    for (let index = 0; index < stale.length; index++) {
      this.offline.delete(stale[index]);
    }

    const staleProgress: string[] = [];
    const progressKeys = this.progress.keys();
    while (progressKeys.hasNext()) {
      const key = progressKeys.next().value as string;
      if (identities.indexOf(key) < 0) {
        staleProgress.push(key);
      }
    }
    for (let index = 0; index < staleProgress.length; index++) {
      this.progress.delete(staleProgress[index]);
    }
  }

  clear(): void {
    this.offline.clear();
    this.progress.clear();
  }
}

/**
 * Search matching used by both Saved tabs.
 *
 * Matching is accent insensitive and case insensitive and always runs against a
 * single, currently visible value: an article row is matched on its title and
 * on the titles of the collections that hold it, a collection row on its title
 * and description. Search never mutates membership.
 */
export class SavedTextSearch {
  private static readonly FOLDING: string =
    'àáâãäåāăą=>aaaaaa' +
    'çćĉċč=>c' +
    'ďđ=>d' +
    'èéêëēĕėęě=>eeeee' +
    'ĝğġģ=>g' +
    'ĥħ=>h' +
    'ìíîïĩīĭįı=>iiiii' +
    'ĵ=>j' +
    'ķ=>k' +
    'ĺļľŀł=>l' +
    'ñńņňŉ=>n' +
    'òóôõöøōŏő=>ooooo' +
    'ŕŗř=>r' +
    'śŝşš=>s' +
    'ţťŧ=>t' +
    'ùúûüũūŭůűų=>uuuuu' +
    'ŵ=>w' +
    'ýÿŷ=>yy' +
    'źżž=>z';

  private static readonly ACCENTS: Map<string, string> = SavedTextSearch.buildFoldingTable();

  private static buildFoldingTable(): Map<string, string> {
    const table: Map<string, string> = new Map<string, string>();
    const groups: string[] = SavedTextSearch.FOLDING.split(' ');
    for (let index = 0; index < groups.length; index++) {
      const group = groups[index];
      const separator = group.indexOf('=>');
      if (separator <= 0) {
        continue;
      }
      const sources = group.substring(0, separator);
      const target = group.substring(separator + 2);
      for (let source = 0; source < sources.length; source++) {
        table.set(sources.charAt(source), target);
      }
    }
    return table;
  }

  /** Lower cases and removes diacritics so that "cafe" matches "Café". */
  static normalise(value: string): string {
    const lowered = value.toLowerCase();
    let folded = '';
    for (let index = 0; index < lowered.length; index++) {
      const character = lowered.charAt(index);
      const replacement = SavedTextSearch.ACCENTS.get(character);
      folded = folded + (replacement !== undefined ? replacement : character);
    }
    return folded;
  }

  static matches(candidate: string, normalisedQuery: string): boolean {
    if (normalisedQuery.length === 0) {
      return true;
    }
    return SavedTextSearch.normalise(candidate).indexOf(normalisedQuery) >= 0;
  }

  /** Normalises the raw query once so that matching stays cheap. */
  static prepareQuery(query: string): string {
    return SavedTextSearch.normalise(query.trim());
  }
}

