/**
 * Serialisation of the Saved surface snapshot.
 *
 * The snapshot is what the feature writes into preferences and what it reads
 * back through `SavedStateRestorer`. It carries the reading list tables, the
 * presentation state of the active view, the pending destructive action and the
 * state of the save-article sheet, so a restart restores exactly what the
 * reader was looking at.
 */
import { ReadingListDatabase } from './ReadingListDatabase';
import { SavedUiState } from '../model/SavedUiState';
import { ReadingListPageEntity, RoomListEntity } from '../model/Entities';

interface SnapshotRoomList {
  id: number;
  title: string;
  isDefault: boolean;
  description: string;
  articles: string[];
}

interface SnapshotPageTitle {
  language: string;
  apiTitle: string;
  displayTitle: string;
}

interface SnapshotSaveSheet {
  article: string;
  isSaved: boolean;
  pendingConfirmation: boolean;
}

interface SnapshotSelection {
  enabled: boolean;
  selectedPageIds: number[];
}

interface SnapshotAccount {
  isLoggedIn: boolean;
  isTemporary: boolean;
  userName: string;
}

interface SavedSnapshot {
  roomLists: SnapshotRoomList[];
  selectedTab: string;
  selectedArticleFilter: string;
  searchQuery: string;
  readingListSyncEnabled: boolean;
  undoAvailable: boolean;
  selection: SnapshotSelection;
  account: SnapshotAccount;
  article: SnapshotPageTitle | null;
  saveSheet: SnapshotSaveSheet | null;
  offlineArticles: string[];
  downloadProgress: Record<string, number>;
}

export class SavedSnapshotCodec {
  static encode(database: ReadingListDatabase, state: SavedUiState, offlineIdentities: string[],
    downloadProgress: Record<string, number>): string {
    const snapshot: SavedSnapshot = {
      roomLists: SavedSnapshotCodec.encodeLists(database),
      selectedTab: state.selectedTab,
      selectedArticleFilter: state.selectedArticleFilter,
      searchQuery: state.searchQuery,
      readingListSyncEnabled: state.readingListSyncEnabled,
      undoAvailable: state.undoAvailable,
      selection: {
        enabled: state.selectionEnabled,
        selectedPageIds: SavedSnapshotCodec.copyNumbers(state.selectedRowIds)
      },
      account: {
        isLoggedIn: state.account.isLoggedIn,
        isTemporary: state.account.isTemporary,
        userName: state.account.userName
      },
      article: SavedSnapshotCodec.encodePageTitle(state),
      saveSheet: SavedSnapshotCodec.encodeSaveSheet(state),
      offlineArticles: SavedSnapshotCodec.copyStrings(offlineIdentities),
      downloadProgress: downloadProgress
    };
    return JSON.stringify(snapshot);
  }

  private static encodeLists(database: ReadingListDatabase): SnapshotRoomList[] {
    const lists: RoomListEntity[] = database.allLists();
    const encoded: SnapshotRoomList[] = [];
    for (let index = 0; index < lists.length; index++) {
      const list = lists[index];
      const articles: string[] = [];
      const pages: ReadingListPageEntity[] = database.activePagesForList(list.id);
      for (let inner = 0; inner < pages.length; inner++) {
        articles.push(pages[inner].identity);
      }
      encoded.push({
        id: list.id,
        title: list.title,
        isDefault: list.isDefault,
        description: list.description,
        articles: articles
      });
    }
    return encoded;
  }

  private static encodePageTitle(state: SavedUiState): SnapshotPageTitle | null {
    const sheet = state.saveSheet;
    if (sheet === null || !sheet.visible) {
      return null;
    }
    return { language: sheet.language, apiTitle: sheet.apiTitle, displayTitle: sheet.displayTitle };
  }

  private static encodeSaveSheet(state: SavedUiState): SnapshotSaveSheet | null {
    const sheet = state.saveSheet;
    if (sheet === null || !sheet.visible) {
      return null;
    }
    return {
      article: sheet.article,
      isSaved: sheet.isSaved,
      pendingConfirmation: sheet.pendingConfirmation
    };
  }

  private static copyNumbers(values: number[]): number[] {
    const copy: number[] = [];
    for (let index = 0; index < values.length; index++) {
      copy.push(values[index]);
    }
    return copy;
  }

  private static copyStrings(values: string[]): string[] {
    const copy: string[] = [];
    for (let index = 0; index < values.length; index++) {
      copy.push(values[index]);
    }
    return copy;
  }
}

/**
 * Application entry point of the Saved feature.
 *
 * The store wires the reading list database, the reactive DAOs, the persisted
 * preferences, the session and the external boundaries into one object, then
 * hands the resulting state to the page. It also implements the page contract
 * that the surrounding application drives.
 */
import { common } from '@kit.AbilityKit';
import { SavedInput, SavedPageOwner } from '../integration/SavedPageIntegration';
import { ReadingListDatabase } from '../saved/data/ReadingListDatabase';
import { ReadingListsDao } from '../saved/data/ReadingListsDao';
import { ReadingListPagesDao } from '../saved/data/ReadingListPagesDao';
import { SavedPreferences } from '../saved/data/SavedPreferences';
import { SavedSession } from '../saved/data/SavedSession';
import { ArticleMediaStatus } from '../saved/data/ArticleMediaStatus';
import { SavedSnapshotCodec } from '../saved/data/SavedSnapshotCodec';
import {
  RestoredContext,
  RestoredSortModes,
  RestoredSummary,
  SavedStateRestorer
} from '../saved/data/SavedStateRestorer';
import { SavedEnvironment } from '../saved/leaf/ExternalGateway';
import { SavedViewModel } from '../saved/viewmodel/SavedViewModel';
import { PageTitle } from '../saved/model/PageTitle';
import { SavedUiState } from '../saved/model/SavedUiState';
import {
  PREFERENCE_ARTICLE_SORT_MODE,
  PREFERENCE_COLLECTION_SORT_MODE,
  PREFERENCE_DATABASE_SNAPSHOT,
  PREFERENCE_LAST_TAB,
  PREFERENCE_SNAPSHOT_KEY,
  PREFERENCE_SYNC_ENABLED
} from '../saved/model/SavedConstants';

function clone(value: Record<string, Object>): Record<string, Object> {
  return JSON.parse(JSON.stringify(value)) as Record<string, Object>;
}

export class LegacySavedStore implements SavedPageOwner {
  private readonly database: ReadingListDatabase;
  private readonly listsDao: ReadingListsDao;
  private readonly pagesDao: ReadingListPagesDao;
  private readonly preferences: SavedPreferences;
  private readonly environment: SavedEnvironment;
  private readonly session: SavedSession;
  private readonly mediaStatus: ArticleMediaStatus;
  private readonly viewModel: SavedViewModel;
  private readonly persistence: Record<string, Object>;
  private readonly runtimeOwnerId: string;
  private readonly summary: RestoredSummary;
  private mounted: boolean = false;

  private constructor(database: ReadingListDatabase, listsDao: ReadingListsDao, pagesDao: ReadingListPagesDao,
    preferences: SavedPreferences, environment: SavedEnvironment, session: SavedSession,
    mediaStatus: ArticleMediaStatus, viewModel: SavedViewModel, persistence: Record<string, Object>,
    summary: RestoredSummary) {
    this.database = database;
    this.listsDao = listsDao;
    this.pagesDao = pagesDao;
    this.preferences = preferences;
    this.environment = environment;
    this.session = session;
    this.mediaStatus = mediaStatus;
    this.viewModel = viewModel;
    this.persistence = persistence;
    this.summary = summary;
    this.runtimeOwnerId = 'SavedStore:' + String(Date.now());
  }

  /**
   * Builds the feature from the surrounding application: restores the persisted
   * snapshot, applies the session state handed to it and starts the reactive
   * projections.
   */
  static async create(context: common.UIAbilityContext, input: SavedInput): Promise<LegacySavedStore> {
    const preferences = await SavedPreferences.create(context, SavedPreferences.defaultStoreName());
    const environment = new SavedEnvironment(input.leaf);
    const database = new ReadingListDatabase();
    const listsDao = new ReadingListsDao(database);
    const pagesDao = new ReadingListPagesDao(database, listsDao);
    const session = new SavedSession();
    const mediaStatus = new ArticleMediaStatus();
    const viewModel = new SavedViewModel(database, listsDao, pagesDao, preferences, environment, session,
      mediaStatus);

    // Persisted preferences seed the store before the snapshot is applied so
    // that both sort modes survive a restart independently.
    const seededSortModes = LegacySavedStore.seedPreferences(preferences, input.persistence);

    const restoredContext = new RestoredContext(database, listsDao, pagesDao, session, mediaStatus, environment,
      viewModel);
    const summary = SavedStateRestorer.restore(LegacySavedStore.resolveRestoredState(input), restoredContext);

    if (!summary.sortModesRestored) {
      const fromPreferences = seededSortModes !== undefined ? seededSortModes : LegacySavedStore
        .readSortModes(input.persistence);
      if (fromPreferences !== undefined) {
        viewModel.applyPersistedSortModes(
          fromPreferences.ALL_ARTICLES !== undefined ? fromPreferences.ALL_ARTICLES : 0,
          fromPreferences.COLLECTIONS !== undefined ? fromPreferences.COLLECTIONS : 0);
      } else {
        viewModel.applyPersistedSortModes(preferences.articleSortMode(), preferences.collectionSortMode());
      }
    }

    viewModel.start();
    const store = new LegacySavedStore(database, listsDao, pagesDao, preferences, environment, session,
      mediaStatus, viewModel, clone(input.persistence), summary);
    store.mounted = true;
    store.viewModel.observe((): void => {
      store.persistSnapshot();
    });
    await store.persistSnapshot();
    return store;
  }

  /* -------------------------------------------------------------------- */
  /* Persistence                                                            */
  /* -------------------------------------------------------------------- */

  private static async seedPreferences(preferences: SavedPreferences,
    persistence: Record<string, Object>): Promise<RestoredSortModes | undefined> {
    const modes = LegacySavedStore.readSortModes(persistence);
    if (modes === undefined) {
      return undefined;
    }
    if (modes.ALL_ARTICLES !== undefined) {
      await preferences.setArticleSortMode(modes.ALL_ARTICLES);
    }
    if (modes.COLLECTIONS !== undefined) {
      await preferences.setCollectionSortMode(modes.COLLECTIONS);
    }
    return modes;
  }

  private static readSortModes(persistence: Record<string, Object>): RestoredSortModes | undefined {
    const raw = LegacySavedStore.lookup(persistence, 'persistedSortModes');
    if (raw === undefined) {
      return LegacySavedStore.lookup(persistence, 'sortModes');
    }
    const parsed = JSON.parse(JSON.stringify(raw)) as RestoredSortModes;
    if (parsed === undefined || parsed === null) {
      return undefined;
    }
    return parsed;
  }

  private static lookup(bag: Record<string, Object>, key: string): Object | undefined {
    const keys: string[] = Object.keys(bag);
    for (let index = 0; index < keys.length; index++) {
      if (keys[index] === key) {
        return bag[keys[index]];
      }
    }
    return undefined;
  }

  /**
   * The state handed to the store wins over the persisted snapshot; anything it
   * does not mention keeps its persisted value.
   */
  private static resolveRestoredState(input: SavedInput): Record<string, Object> {
    const merged: Record<string, Object> = {};
    const stored = LegacySavedStore.lookup(input.persistence, PREFERENCE_SNAPSHOT_KEY);
    if (stored !== undefined) {
      const snapshotRecord = LegacySavedStore.asRecord(stored);
      if (snapshotRecord !== undefined) {
        const keys: string[] = Object.keys(snapshotRecord);
        for (let index = 0; index < keys.length; index++) {
          merged[keys[index]] = snapshotRecord[keys[index]];
        }
      }
    }
    const keys: string[] = Object.keys(input.state);
    for (let index = 0; index < keys.length; index++) {
      merged[keys[index]] = input.state[keys[index]];
    }
    return merged;
  }

  private static asRecord(value: Object): Record<string, Object> | undefined {
    const text: string = JSON.stringify(value);
    if (text.length < 2 || text.charAt(0) !== '{') {
      return undefined;
    }
    return JSON.parse(text) as Record<string, Object>;
  }

  private persistSnapshot(): void {
    const state = this.viewModel.currentState();
    const encoded = SavedSnapshotCodec.encode(this.database, state, [], {});
    this.persistence['snapshot'] = encoded;
    this.persistence['saved_database_snapshot'] = encoded;
    this.persistence[PREFERENCE_SNAPSHOT_KEY] = encoded;
    this.persistence['persistedSortModes'] = {
      ALL_ARTICLES: state.articleSortMode,
      COLLECTIONS: state.collectionSortMode
    };
    this.persistence[PREFERENCE_ARTICLE_SORT_MODE] = String(state.articleSortMode);
    this.persistence[PREFERENCE_COLLECTION_SORT_MODE] = String(state.collectionSortMode);
    this.persistence[PREFERENCE_LAST_TAB] = state.selectedTab;
    this.persistence[PREFERENCE_SYNC_ENABLED] = state.readingListSyncEnabled ? 'true' : 'false';
    this.persistence[PREFERENCE_DATABASE_SNAPSHOT] = encoded;
    this.writeThrough();
  }

  private writeThrough(): void {
    const state = this.viewModel.currentState();
    this.preferences.setArticleSortMode(state.articleSortMode);
    this.preferences.setCollectionSortMode(state.collectionSortMode);
    this.preferences.setLastTab(state.selectedTab);
    this.preferences.setSyncEnabled(state.readingListSyncEnabled);
    this.preferences.persistSnapshot(String(this.persistence[PREFERENCE_SNAPSHOT_KEY]));
  }

  /* -------------------------------------------------------------------- */
  /* Page contract                                                          */
  /* -------------------------------------------------------------------- */

  mount(_context: common.UIAbilityContext, _input: SavedInput): Promise<void> {
    this.mounted = true;
    return Promise.resolve();
  }

  openSavedSurface(): Promise<void> {
    return this.viewModel.openSavedSurface();
  }

  selectSavedTab(tab: string): Promise<void> {
    return this.viewModel.selectSavedTab(tab);
  }

  enterSavedSearchQuery(query: string, elapsedMillis: number): Promise<void> {
    return this.viewModel.enterSavedSearchQuery(query, elapsedMillis);
  }

  selectArticleFilter(filter: string): Promise<void> {
    return this.viewModel.selectArticleFilter(filter);
  }

  selectAllVisibleRows(): Promise<void> {
    return this.viewModel.selectAllVisibleRows();
  }

  openSaveArticleSheet(): Promise<void> {
    return this.viewModel.openSaveArticleSheet();
  }

  cancelUnsaveConfirmation(): Promise<void> {
    return this.viewModel.cancelUnsaveConfirmation();
  }

  undoArticleDeletion(): Promise<void> {
    return this.viewModel.undoArticleDeletion();
  }

  resumeQueuedCollectionToggle(): Promise<void> {
    return this.viewModel.resumeQueuedCollectionToggle();
  }

  retryPullToRefreshAndCompleteSync(): Promise<void> {
    return this.viewModel.pullToRefresh();
  }

  /* -------------------------------------------------------------------- */
  /* Observations                                                           */
  /* -------------------------------------------------------------------- */

  currentState(): Record<string, Object> {
    const state: SavedUiState = this.viewModel.currentState();
    const projection: Record<string, Object> = JSON.parse(JSON.stringify(state)) as Record<string, Object>;
    projection['previousRefreshOutcome'] = this.summary.previousRefreshOutcome;
    projection['previousSyncStarted'] = this.summary.previousSyncStarted;
    projection['defaultCollectionTitle'] = this.summary.defaultCollectionTitle;
    projection['surfaceOpen'] = this.viewModel.isSurfaceOpen();
    projection['deduplicatedArticleCount'] = state.articleRows.length;
    projection['userCollectionCount'] = this.listsDao.countUserCollections();
    projection['collectionCountInDatabase'] = this.database.countLists();
    return projection;
  }

  currentPersistence(): Record<string, Object> {
    return clone(this.persistence);
  }

  featureAvailable(): boolean {
    return this.mounted && this.viewModel !== undefined;
  }

  ownerId(): string {
    return this.runtimeOwnerId;
  }

  /* -------------------------------------------------------------------- */
  /* Production surface used by the page                                    */
  /* -------------------------------------------------------------------- */

  state(): SavedUiState {
    return this.viewModel.currentState();
  }

  features(): SavedViewModel {
    return this.viewModel;
  }

  defaultCollectionTitle(): string {
    return this.summary.defaultCollectionTitle;
  }

  previousRefreshOutcome(): string {
    return this.summary.previousRefreshOutcome;
  }

  previousSyncStarted(): boolean {
    return this.summary.previousSyncStarted;
  }

  savedSessions(): SavedSession {
    return this.session;
  }

  media(): ArticleMediaStatus {
    return this.mediaStatus;
  }

  readingLists(): ReadingListsDao {
    return this.listsDao;
  }

  savedPages(): ReadingListPagesDao {
    return this.pagesDao;
  }

  environment(): SavedEnvironment {
    return this.environment;
  }

  /** Restores this store from a page title, the way an article entry point does. */
  prepareSaveArticleSheet(pageTitle: PageTitle): void {
    this.viewModel.setPendingPageTitle(pageTitle);
  }
}

