/**
   * The state handed to the store wins over the persisted snapshot; anything it
   * does not mention keeps its persisted value. When nothing was handed in, the
   * snapshot that preferences wrote on the previous run is restored.
   */
  private static resolveRestoredState(input: SavedInput, persistedSnapshot: string): Record<string, Object> {
    const merged: Record<string, Object> = {};
    let restored: Record<string, Object> | undefined = undefined;
    const stored = LegacySavedStore.lookup(input.persistence, PREFERENCE_SNAPSHOT_KEY);
    if (stored !== undefined) {
      restored = LegacySavedStore.asRecord(stored);
    }
    if (restored === undefined && persistedSnapshot.length > 0) {
      restored = LegacySavedStore.asRecordFromText(persistedSnapshot);
    }
    if (restored !== undefined) {
      const keys: string[] = Object.keys(restored);
      for (let index = 0; index < keys.length; index++) {
        merged[keys[index]] = restored[keys[index]];
      }
    }
    const keys: string[] = Object.keys(input.state);
    for (let index = 0; index < keys.length; index++) {
      merged[keys[index]] = input.state[keys[index]];
    }
    return merged;
  }

  private static asRecord(value: Object): Record<string, Object> | undefined {
    const text: string = JSON.stringify(value);
    if (text.length < 2 || text.charAt(0) !== '{') {
      return undefined;
    }
    return JSON.parse(text) as Record<string, Object>;
  }

  private static asRecordFromText(text: string): Record<string, Object> | undefined {
    if (text.length < 2 || text.charAt(0) !== '{') {
      return undefined;
    }
    return JSON.parse(text) as Record<string, Object>;
  }

