input.content:
/**
 * Production wiring of the Saved feature.
 *
 * The application injects the restored session snapshot and the services the
 * feature is allowed to talk to; everything else - the reading list tables, the
 * projections, the persistence and the recovery behaviour - is owned by the
 * feature.
 */
import { common } from '@kit.AbilityKit';
import { SavedEffect, SavedInput, SavedLeaf } from '../integration/SavedPageIntegration';
import { LegacySavedStore } from '../model/LegacySavedStore';

/**
 * Leaf sink of the surrounding application. The feature publishes every
 * external call here; the sink only records or forwards it.
 */
export class ApplicationLeafSink implements SavedLeaf {
  private readonly published: SavedEffect[] = [];

  emit(effect: SavedEffect): Promise<void> {
    this.published.push(effect);
    return Promise.resolve();
  }

  publishedEffects(): SavedEffect[] {
    return this.published.slice();
  }

  clear(): void {
    this.published.length = 0;
  }
}

/** Session snapshot handed to the feature when the app starts. */
export class ProductionSavedInput implements SavedInput {
  state: Record<string, Object>;
  persistence: Record<string, Object>;
  leaf: SavedLeaf;

  constructor(leaf: SavedLeaf, state: Record<string, Object>, persistence: Record<string, Object>) {
    this.state = state;
    this.persistence = persistence;
    this.leaf = leaf;
  }
}

export class SavedFeature {
  /**
   * Creates the feature from an already restored session. An empty snapshot is
   * a valid input: the persisted reading lists are then restored from
   * preferences, which is what happens on a first run and after a restart.
   */
  static async create(context: common.UIAbilityContext, leaf: SavedLeaf,
    state: Record<string, Object>, persistence: Record<string, Object>): Promise<LegacySavedStore> {
    return LegacySavedStore.create(context, new ProductionSavedInput(leaf, state, persistence));
  }

  /** Creates the feature with the default application services. */
  static async createWithDefaults(context: common.UIAbilityContext): Promise<LegacySavedStore> {
    const sink = new ApplicationLeafSink();
    const store = await LegacySavedStore.create(context, new ProductionSavedInput(sink, emptyRecord(),
      emptyRecord()));
    await store.openSavedSurface();
    return store;
  }
}

function emptyRecord(): Record<string, Object> {
  return JSON.parse('{}') as Record<string, Object>;
}

import { common } from '@kit.AbilityKit';
import { CallbackSavedPageOwner, SavedInput, SavedPageOwner } from '../integration/SavedPageIntegration';
import { LegacySavedStore } from '../model/LegacySavedStore';
import { SavedFeature } from '../saved/SavedFeature';
import { SavedPage } from '../saved/ui/SavedPage';

/**
 * Host page of the Saved experience.
 *
 * The page owns the runtime owner used by the surrounding application to drive
 * the feature, and renders the Saved surface once the feature is mounted.
 */
@Entry
@Component
struct Index {
  @State mounted: boolean = false;
  @State failure: string = '';
  private store?: LegacySavedStore;
  private injectedInput?: SavedInput;
  private runtimeOwnerId: string = 'SavedIndex:' + String(Date.now());

  async aboutToAppear(): Promise<void> {
    await this.bootstrap();
  }

  /**
   * Creates the feature. A session snapshot handed in by the surrounding
   * application wins; otherwise the persisted state is restored.
   */
  async bootstrap(): Promise<void> {
    if (this.store !== undefined) {
      return;
    }
    try {
      const context: common.UIAbilityContext = this.abilityContext();
      const input: SavedInput = this.injectedInput !== undefined ? this.injectedInput
        : SavedFeature.defaultInput();
      this.store = await LegacySavedStore.create(context, input);
      await this.store.openSavedSurface();
      this.mounted = true;
      this.failure = '';
    } catch (error) {
      this.mounted = false;
      this.failure = 'The Saved page is unavailable right now.';
    }
  }

  /** Hands a restored session snapshot to the page before it is mounted. */
  attachInput(input: SavedInput): void {
    this.injectedInput = input;
  }

  /** Binds an already built store, for example when it was mounted elsewhere. */
  attachStore(store: LegacySavedStore): void {
    this.store = store;
    this.mounted = true;
  }

  featureStore(): LegacySavedStore | undefined {
    return this.store;
  }

  private abilityContext(): common.UIAbilityContext {
    return this.getUIContext().getHostContext() as common.UIAbilityContext;
  }

  createRuntimeOwner(): SavedPageOwner {
    return new CallbackSavedPageOwner(
      async (context: common.UIAbilityContext, input: SavedInput): Promise<void> => {
        this.injectedInput = input;
        this.store = await LegacySavedStore.create(context, input);
        this.mounted = true;
      },
      [
        async (): Promise<void> => { await this.store?.openSavedSurface(); },
        async (tab: Object): Promise<void> => { await this.store?.selectSavedTab(String(tab)); },
        async (query: Object, elapsed: Object): Promise<void> => {
          await this.store?.enterSavedSearchQuery(String(query), Number(elapsed));
        },
        async (filter: Object): Promise<void> => { await this.store?.selectArticleFilter(String(filter)); },
        async (): Promise<void> => { await this.store?.selectAllVisibleRows(); },
        async (): Promise<void> => { await this.store?.openSaveArticleSheet(); },
        async (): Promise<void> => { await this.store?.cancelUnsaveConfirmation(); },
        async (): Promise<void> => { await this.store?.undoArticleDeletion(); },
        async (): Promise<void> => { await this.store?.resumeQueuedCollectionToggle(); },
        async (): Promise<void> => { await this.store?.retryPullToRefreshAndCompleteSync(); }
      ],
      (): Record<string, Object> => this.store?.currentState() ?? SavedFeature.emptyStateRecord(),
      (): Record<string, Object> => this.store?.currentPersistence() ?? SavedFeature.emptyStateRecord(),
      (): boolean => this.store?.featureAvailable() ?? false,
      (): string => this.runtimeOwnerId
    );
  }

  build() {
    Column({ space: 16 }) {
      if (this.mounted && this.store !== undefined) {
        SavedPage({ store: this.store })
      } else if (this.failure.length > 0) {
        Text(this.failure)
          .fontSize(16)
      } else {
        LoadingProgress()
          .width(40)
          .height(40)
      }
    }
    .width('100%')
    .height('100%')
  }
}

