    const state = this.viewModel.currentState();
    const fingerprint: string = state.articleSortMode + '|' + state.collectionSortMode + '|' + state.selectedTab + '|'
      + String(state.readingListSyncEnabled);
    if (fingerprint === this.lastWriteFingerprint) {
      return;
