    this.lastWriteFingerprint = fingerprint;
    this.preferences.setArticleSortMode(state.articleSortMode);
    this.preferences.setCollectionSortMode(state.collectionSortMode);
    this.preferences.setLastTab(state.selectedTab);
    this.preferences.setSyncEnabled(state.readingListSyncEnabled);
    this.preferences.persistSnapshot(String(this.persistence[PREFERENCE_SNAPSHOT_KEY]));
  }

