export class PersistedSortModes {
  ALL_ARTICLES: number;
  COLLECTIONS: number;

  constructor(articleSortMode: number, collectionSortMode: number) {
    this.ALL_ARTICLES = articleSortMode;
    this.COLLECTIONS = collectionSortMode;
  }
}

/** The visible Saved surface, projected for observation. */
export class SavedSurfaceProjection {
  selectedTab: string;
  articleRowIds: number[];
  collectionRowIds: number[];
  selectedPageIds: number[];
  selectionEnabled: boolean;
  searchQuery: string;
  selectedArticleFilter: string;
  articleSortMode: number;
  collectionSortMode: number;
  isLoading: boolean;
  isRefreshing: boolean;
  emptyState: string;
  onboarding: string;

  constructor(state: SavedUiState) {
    this.selectedTab = state.selectedTab;
    this.articleRowIds = state.articleRowIds();
    this.collectionRowIds = state.collectionRowIds();
    this.selectedPageIds = state.selectedRowIds;
    this.selectionEnabled = state.selectionEnabled;
